import Foundation
import WebKit

// MARK: - Authentication Library for Processing User Profile Uploads

protocol HTMLSanitizer {
    func sanitize(_ input: String) -> String
}

class StrictHTMLSanitizer: HTMLSanitizer {
    private let allowedTags: Set<String> = ["b", "i", "em", "strong", "p", "br"]

    func sanitize(_ input: String) -> String {
        var result = input
        // Remove script tags
        let scriptPattern = "<script[^>]*>[\\s\\S]*?</script>"
        if let regex = try? NSRegularExpression(pattern: scriptPattern, options: .caseInsensitive) {
            result = regex.stringByReplacingMatches(in: result, range: NSRange(result.startIndex..., in: result), withTemplate: "")
        }
        // Remove event handlers
        let eventPattern = "\\son\\w+\\s*=\\s*[\"'][^\"']*[\"']"
        if let regex = try? NSRegularExpression(pattern: eventPattern, options: .caseInsensitive) {
            result = regex.stringByReplacingMatches(in: result, range: NSRange(result.startIndex..., in: result), withTemplate: "")
        }
        return result
    }
}

struct UserProfile {
    let username: String
    let displayName: String
    let bio: String
    let avatarURL: String?
    let metadata: [String: String]
}

class ProfileUploadProcessor {
    private let sanitizer: HTMLSanitizer
    private let encodingStrategy: ContentEncodingStrategy

    init(sanitizer: HTMLSanitizer = StrictHTMLSanitizer(),
         encodingStrategy: ContentEncodingStrategy = .standard) {
        self.sanitizer = sanitizer
        self.encodingStrategy = encodingStrategy
    }

    func processUpload(data: Data, contentType: String) throws -> UserProfile {
        guard let jsonObject = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            throw ProcessingError.invalidFormat
        }

        let username = (jsonObject["username"] as? String) ?? ""
        let displayName = (jsonObject["display_name"] as? String) ?? ""
        let bio = (jsonObject["bio"] as? String) ?? ""
        let avatarURL = jsonObject["avatar_url"] as? String
        let metadata = (jsonObject["metadata"] as? [String: String]) ?? [:]

        let sanitizedBio = sanitizer.sanitize(bio)
        let sanitizedName = sanitizer.sanitize(displayName)

        return UserProfile(
            username: username,
            displayName: sanitizedName,
            bio: sanitizedBio,
            avatarURL: avatarURL,
            metadata: metadata
        )
    }
}

enum ContentEncodingStrategy {
    case standard
    case legacy
}

enum ProcessingError: Error {
    case invalidFormat
    case unauthorized
}

// MARK: - Profile Rendering for WebView-based Auth UI

class AuthenticationUIRenderer {
    private let webView: WKWebView
    private let templateEngine: TemplateEngine

    init(webView: WKWebView) {
        self.webView = webView
        self.templateEngine = TemplateEngine()
    }

    func renderProfileConfirmation(profile: UserProfile, authToken: String) {
        let context = buildRenderContext(profile: profile, token: authToken)
        let html = templateEngine.render(template: .profileConfirmation, context: context)
        webView.loadHTMLString(html, baseURL: URL(string: "https://auth.internal"))
    }

    private func buildRenderContext(profile: UserProfile, token: String) -> [String: String] {
        var context: [String: String] = [
            "username": escapeForHTMLAttribute(profile.username),
            "display_name": escapeForHTMLContent(profile.displayName),
            "bio": profile.bio,  // Already sanitized by processor
            "auth_token": token
        ]

        // Merge metadata into context for template rendering
        for (key, value) in profile.metadata {
            let safeKey = key.replacingOccurrences(of: "<", with: "")
                             .replacingOccurrences(of: ">", with: "")
            context["meta_\(safeKey)"] = escapeForHTMLContent(value)
        }

        return context
    }

    private func escapeForHTMLContent(_ input: String) -> String {
        return input
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
    }

    private func escapeForHTMLAttribute(_ input: String) -> String {
        return input
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&#x27;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
    }
}

// MARK: - Template Engine

class TemplateEngine {
    enum Template: String {
        case profileConfirmation = "profile_confirmation"
    }

    func render(template: Template, context: [String: String]) -> String {
        let baseHTML = getTemplate(template)
        return interpolate(template: baseHTML, context: context)
    }

    private func interpolate(template: String, context: [String: String]) -> String {
        var result = template
        for (key, value) in context {
            result = result.replacingOccurrences(of: "{{\(key)}}", with: value)
        }
        return result
    }

    private func getTemplate(_ template: Template) -> String {
        switch template {
        case .profileConfirmation:
            return """
            <!DOCTYPE html>
            <html>
            <head><title>Confirm Profile</title></head>
            <body>
                <div class="profile-card">
                    <h2>{{display_name}}</h2>
                    <p class="username">@{{username}}</p>
                    <div class="bio">{{bio}}</div>
                    <div class="metadata">{{meta_tagline}}</div>
                </div>
                <form method="POST" action="/auth/confirm">
                    <input type="hidden" name="token" value="{{auth_token}}">
                    <button type="submit">Confirm Identity</button>
                </form>
                <script>
                    document.querySelector('form').addEventListener('submit', function(e) {
                        e.preventDefault();
                        window.webkit.messageHandlers.authConfirm.postMessage({
                            token: document.querySelector('[name=token]').value
                        });
                    });
                </script>
            </body>
            </html>
            """
        }
    }
}
